#include "cryptoutils.h"
int main(void){long long n=3599,e=31,m=59,c=cu_modpow((unsigned long long)m,(unsigned long long)e,(unsigned long long)n);printf("Illustration with n=%lld and known plaintext block m=%lld\nCiphertext c=m^e mod n = %llu\n",n,m,c);long long a=m,b=n;while(b){long long t=a%b;a=b;b=t;}printf("gcd(m,n) = %lld, which reveals a nontrivial factor of n.\n",a);a=(long long)c;b=n;while(b){long long t=a%b;a=b;b=t;}printf("gcd(c,n) = %lld. Since c=m^e mod n, a plaintext factor shared with n also makes c share that factor.\n",a);puts("If you know only that some unknown plaintext block shares a factor but do not know its numeric value/ciphertext, that statement alone does not tell you the factor.");return 0;}
